     private List<TaskItem> inProgressTasks => allTasks.Where(t => t.Status == StatusInProgress).ToList();
     private List<TaskItem> doneTasks => allTasks.Where(t => t.Status == StatusDone).ToList();

     protected override async Task OnInitializedAsync()
     {
         await LoadTasks();
     }

     private async Task LoadTasks()
     {
         try
         {
             loading = true;
             errorMessage = null;
             allTasks = await TaskService.GetAllTasksAsync();
         }
         catch (Exception ex)
         {
             errorMessage = ex.Message;
         }
         finally
         {
             loading = false;
         }
     }

     private List<TaskItem> FilteredTasks(List<TaskItem> tasks)
     {
         if (string.IsNullOrWhiteSpace(searchText))
             return tasks;

         return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
     }

     private void HandleSearchChanged(string value)
     {
         searchText = value;
     }

     private async Task MoveTask(int taskId, string newStatus)
     {
         try
         {
             await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
             var task = allTasks.First(t => t.Id == taskId);
             var index = allTasks.IndexOf(task);
             allTasks[index] = task with { Status = newStatus };
         }
         catch (Exception ex)
         {
             errorMessage = ex.Message;
         }
     }

     private async Task CreateTask(TaskItem formData, string status)
     {
         try
         {
             var created = await TaskService.CreateTaskAsync(formData.Title, formData.Assignee, formData.Priority, formData.DueDate);
             allTasks.Add(created with { Status = status });
         }
         catch (Exception ex)
         {
             errorMessage = ex.Message;
         }
     }
 }

